'use strict';

/**
 * 测试者复核脚本（草稿区，非交付物）：用 node:http 原始客户端确认
 * 「超过 1MB 的请求体」到底会不会收到 README §4 承诺的 413 PAYLOAD_TOO_LARGE。
 *
 * 运行：node temp/测试者/probe-413.cjs
 */

const http = require('node:http');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const { createServer } = require('../../src/server.js');

(async () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kanban-413-probe-'));
  const dataFile = path.join(dir, 'tasks.json');
  const app = await createServer({ dataFile, port: 0 });

  const body = JSON.stringify({ title: '大任务', pad: 'x'.repeat(1024 * 1024 + 64) });
  console.log('请求体字节数 =', Buffer.byteLength(body), '(上限 1 MiB =', 1024 * 1024, ')');

  const result = await new Promise((resolve) => {
    const req = http.request({
      host: '127.0.0.1',
      port: app.port,
      path: '/api/tasks',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(body),
      },
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => resolve({ kind: 'HTTP 响应', status: res.statusCode, body: data.slice(0, 200) }));
    });
    req.on('error', (err) => resolve({ kind: '连接错误（未收到任何 HTTP 响应）', code: err.code, message: err.message }));
    req.end(body);
  });

  console.log('结果：', JSON.stringify(result, null, 2));

  await app.close();
  fs.rmSync(dir, { recursive: true, force: true });
})();

